using System;using System.IO;using System.Linq;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;
namespace VideoGame.Editor {
public static class UndercityEnemyAssets {
 const string Root="Assets/Game/Resources/Detailed/UndercityEnemies/",Animations="Assets/Game/Resources/UndercityEnemyAnimations/",SourceMotions="Assets/Game/Authoring/UndercityEnemies/SourceMotions",Out="artifacts/biome-parallel/enemy-production/undercity/";
 [Serializable]class Maps{public string Albedo,Normal,Emission;}[Serializable]class Surface{public string name,id;public Maps maps;public float[] color;public float metallic,roughness;}[Serializable]class Model{public Surface[] materials;public int bones,triangles;}[Serializable]class Manifest{public Model UndercityMelee,UndercityGunner,UndercityAoe,UndercityHeavy;}
 static readonly string[] Ids={"UndercityMelee","UndercityGunner","UndercityAoe","UndercityHeavy"};
 public static void BuildAndProof(){Build();Proof();}
 [MenuItem("Nexus/Rebuild Undercity enemies")]public static void Build(){
 ConfigureImports();
 var data=JsonUtility.FromJson<Manifest>(File.ReadAllText(Root+"manifest.json"));Directory.CreateDirectory(Root+"Materials");Directory.CreateDirectory(Root+"Prefabs");AssetDatabase.Refresh();
 foreach(var id in Ids){var info=id.EndsWith("Melee")?data.UndercityMelee:id.EndsWith("Gunner")?data.UndercityGunner:id.EndsWith("Aoe")?data.UndercityAoe:data.UndercityHeavy;string source=Root+"Models/"+id+".fbx";var model=UnityEngine.Object.Instantiate(AssetDatabase.LoadAssetAtPath<GameObject>(source));model.name=id;var clips=AssetDatabase.LoadAllAssetsAtPath(source).Concat(Directory.GetFiles(SourceMotions,id+"_*.fbx").SelectMany(file=>AssetDatabase.LoadAllAssetsAtPath(file.Replace((char)92,'/')))).OfType<AnimationClip>().Where(c=>!c.name.StartsWith("__preview__")&&AnimationUtility.GetCurveBindings(c).Length>10).ToArray();
 var idle=clips.Where(c=>id.EndsWith("Gunner")?c.name.Contains("lookingAround"):id.EndsWith("Heavy")?(c.name.EndsWith("IDLE")||AssetDatabase.GetAssetPath(c).EndsWith(id+"_IDLE.fbx")):(c.name.EndsWith("Idle_1")||AssetDatabase.GetAssetPath(c).EndsWith(id+"_Idle_1.fbx"))).OrderByDescending(c=>AssetDatabase.GetAssetPath(c).Contains("SourceMotions")?1:0).ThenByDescending(c=>AnimationUtility.GetCurveBindings(c).Length).FirstOrDefault();if(idle){var pose=RemapPose(idle,model);pose.SampleAnimation(model,0);UnityEngine.Object.DestroyImmediate(pose);}
 foreach(var c in model.GetComponentsInChildren<Animator>())UnityEngine.Object.DestroyImmediate(c);foreach(var c in model.GetComponentsInChildren<Animation>())UnityEngine.Object.DestroyImmediate(c);
 foreach(var r in model.GetComponentsInChildren<Renderer>()){
  r.sharedMaterials=r.sharedMaterials.Select(src=>{var surface=info.materials.FirstOrDefault(m=>src&&src.name.StartsWith(m.name,StringComparison.Ordinal));if(surface==null)throw new Exception(id+" lost material "+src?.name);string path=Root+"Materials/"+id+"_"+surface.id+".mat";var mat=AssetDatabase.LoadAssetAtPath<Material>(path);if(!mat){mat=new Material(Shader.Find("Standard"));AssetDatabase.CreateAsset(mat,path);}mat.mainTexture=Tex(id,surface.maps.Albedo);mat.color=mat.mainTexture?Color.white:new Color(surface.color[0],surface.color[1],surface.color[2],1);mat.SetFloat("_Metallic",surface.metallic);mat.SetFloat("_Glossiness",1-surface.roughness);mat.SetTexture("_MetallicGlossMap",Tex(id,surface.id+"_MetalSmooth.png"));mat.EnableKeyword("_METALLICGLOSSMAP");if(!string.IsNullOrEmpty(surface.maps.Normal)){mat.SetTexture("_BumpMap",Tex(id,surface.maps.Normal));mat.SetFloat("_BumpScale",.7f);mat.EnableKeyword("_NORMALMAP");}if(!string.IsNullOrEmpty(surface.maps.Emission)){mat.SetTexture("_EmissionMap",Tex(id,surface.maps.Emission));mat.SetColor("_EmissionColor",Color.white*.7f);mat.EnableKeyword("_EMISSION");}mat.enableInstancing=true;EditorUtility.SetDirty(mat);return mat;}).ToArray();
  if(r is SkinnedMeshRenderer skin)skin.updateWhenOffscreen=true;
 }
 if(id.EndsWith("Melee")||id.EndsWith("Aoe")||id.EndsWith("Heavy"))model.transform.localRotation=Quaternion.Euler(0,180,0);var bounds=VideoGame.Art.RenderedBounds(model);float target=id.EndsWith("Heavy")?2.5f:id.EndsWith("Melee")?1.95f:id.EndsWith("Aoe")?1.7f:1.9f;model.transform.localScale*=target/bounds.size.y;bounds=VideoGame.Art.RenderedBounds(model);model.transform.position-=new Vector3(bounds.center.x,bounds.min.y,bounds.center.z);
 FitRifle(model,id);Socket(model,id);UndercityProductionClips.Bake(model,id);PreserveNative(clips,model,id);
 Resources.Load<AnimationClip>("UndercityEnemyAnimations/"+id+"/Idle").SampleAnimation(model,0);bounds=VideoGame.Art.RenderedBounds(model);model.transform.position-=new Vector3(bounds.center.x,bounds.min.y,bounds.center.z);PrefabUtility.SaveAsPrefabAsset(model,Root+"Prefabs/"+id+".prefab");UnityEngine.Object.DestroyImmediate(model);
 }AssetDatabase.SaveAssets();Debug.Log("UNDERCITY_ENEMIES_BUILT: four distinct sources,44 gameplay clips.");}
 static AnimationClip RemapPose(AnimationClip source,GameObject model){var clip=UnityEngine.Object.Instantiate(source);foreach(var original in AnimationUtility.GetCurveBindings(clip)){if(original.path==""){AnimationUtility.SetEditorCurve(clip,original,null);continue;}var target=model.GetComponentsInChildren<Transform>().Select(t=>AnimationUtility.CalculateTransformPath(t,model.transform)).FirstOrDefault(path=>path==original.path||path.EndsWith("/"+original.path,StringComparison.Ordinal));if(target!=null&&target!=original.path){var binding=original;var curve=AnimationUtility.GetEditorCurve(clip,binding);AnimationUtility.SetEditorCurve(clip,binding,null);binding.path=target;AnimationUtility.SetEditorCurve(clip,binding,curve);}}return clip;}
 static void ConfigureImports(){
 foreach(string file in Directory.GetFiles(Root+"Models","*.fbx",SearchOption.AllDirectories).Concat(Directory.GetFiles(SourceMotions,"*.fbx"))){var m=(ModelImporter)AssetImporter.GetAtPath(file);if(m.animationType==ModelImporterAnimationType.Legacy&&m.importAnimation&&!m.importCameras&&!m.importLights&&m.isReadable&&m.materialImportMode==ModelImporterMaterialImportMode.ImportStandard)continue;m.animationType=ModelImporterAnimationType.Legacy;m.importAnimation=true;m.importCameras=m.importLights=false;m.isReadable=true;m.materialImportMode=ModelImporterMaterialImportMode.ImportStandard;m.SaveAndReimport();}
 foreach(string file in Directory.GetFiles(Root+"Textures","*.png",SearchOption.AllDirectories)){var m=(TextureImporter)AssetImporter.GetAtPath(file);bool srgb=file.Contains("Albedo")||file.Contains("Emission");var type=file.Contains("Normal")?TextureImporterType.NormalMap:TextureImporterType.Default;if(m.maxTextureSize==2048&&m.sRGBTexture==srgb&&m.textureType==type)continue;m.maxTextureSize=2048;m.sRGBTexture=srgb;m.textureType=type;m.SaveAndReimport();}
 }
 static void PreserveNative(AnimationClip[] clips,GameObject model,string id){
 foreach(string state in ActorAnimationBuilder.Names){string suffix=null;if(id.EndsWith("Aoe"))suffix=state=="Idle"?"Idle_1":state.StartsWith("Run")?"Swim_Forward":state=="Dash"?"Dash_Back":state=="Death"?"Die":state=="Cast"||state=="Fire"||state=="Melee"?"Attack_Heavy":null;else if(id.EndsWith("Heavy"))suffix=state=="Idle"?"IDLE":state.StartsWith("Run")?"RUN":null;else if(id.EndsWith("Gunner")&&state=="Idle")suffix="lookingAround";if(suffix==null)continue;
 var source=clips.Where(c=>c.name.EndsWith(suffix,StringComparison.Ordinal)||AssetDatabase.GetAssetPath(c).EndsWith(id+"_"+suffix+".fbx",StringComparison.Ordinal)).OrderByDescending(c=>AssetDatabase.GetAssetPath(c).Contains("SourceMotions")?1:0).ThenByDescending(c=>AnimationUtility.GetCurveBindings(c).Length).FirstOrDefault();if(!source)throw new Exception(id+" missing native "+suffix);var clip=UnityEngine.Object.Instantiate(source);clip.name=state;clip.legacy=true;clip.wrapMode=state=="Idle"||state.StartsWith("Run")?WrapMode.Loop:WrapMode.ClampForever;
 // Keep source action detail and remove travel from the source rig/root. Body articulation remains authored.
 foreach(var original in AnimationUtility.GetCurveBindings(clip)){var binding=original;if(binding.path==" ".Trim()){AnimationUtility.SetEditorCurve(clip,binding,null);continue;}var target=model.GetComponentsInChildren<Transform>().Select(t=>AnimationUtility.CalculateTransformPath(t,model.transform)).FirstOrDefault(path=>path==binding.path||path.EndsWith("/"+binding.path,StringComparison.Ordinal));if(target!=null&&target!=binding.path){var curve=AnimationUtility.GetEditorCurve(clip,binding);AnimationUtility.SetEditorCurve(clip,binding,null);binding.path=target;AnimationUtility.SetEditorCurve(clip,binding,curve);}if(binding.propertyName=="m_LocalPosition.x"||binding.propertyName=="m_LocalPosition.z"||binding.propertyName=="localPosition.x"||binding.propertyName=="localPosition.z"){
  string name=binding.path.Split('/').Last();if(UndercityProductionClips.Role(name)=="hips"||!binding.path.Contains("/")){var curve=AnimationUtility.GetEditorCurve(clip,binding);float value=curve.Evaluate(0);AnimationUtility.SetEditorCurve(clip,binding,AnimationCurve.Constant(0,clip.length,value));}
 }
 } string path=Animations+id+"/"+state+".anim";var old=AssetDatabase.LoadAssetAtPath<AnimationClip>(path);if(old){EditorUtility.CopySerialized(clip,old);UnityEngine.Object.DestroyImmediate(clip);}else AssetDatabase.CreateAsset(clip,path);
 }
 }
 static void FitRifle(GameObject model,string id){
 if(!(id.EndsWith("Gunner")||id.EndsWith("Heavy")))return;var hand=model.GetComponentsInChildren<Transform>().First(t=>UndercityProductionClips.Role(t.name)=="hand.R");var parts=model.GetComponentsInChildren<MeshRenderer>().Where(r=>r.name.StartsWith("ServiceRifle")).ToArray();if(parts.Length==0)throw new Exception(id+" missing credited rifle");var holder=new GameObject("Measured service rifle grip").transform;holder.SetParent(hand,true);holder.position=Vector3.zero;holder.rotation=Quaternion.identity;var inherited=hand.lossyScale;holder.localScale=new Vector3(1/inherited.x,1/inherited.y,1/inherited.z);foreach(var part in parts)part.transform.SetParent(holder,true);
 var points=parts.SelectMany(r=>r.GetComponent<MeshFilter>().sharedMesh.vertices.Select(v=>r.transform.TransformPoint(v))).ToArray();var b=new Bounds(points[0],Vector3.zero);foreach(var point in points)b.Encapsulate(point);int axis=b.size.x>b.size.y?(b.size.x>b.size.z?0:2):(b.size.y>b.size.z?1:2);float length=b.size[axis];float EndRadius(bool positive){var near=points.Where(v=>positive?v[axis]>b.max[axis]-length*.15f:v[axis]<b.min[axis]+length*.15f).ToArray();var end=new Bounds(near[0],Vector3.zero);foreach(var v in near)end.Encapsulate(v);var size=end.size;size[axis]=0;return size.magnitude;}bool muzzlePositive=EndRadius(true)<EndRadius(false);var direction=Vector3.zero;direction[axis]=muzzlePositive?1:-1;holder.rotation=Quaternion.AngleAxis(90,Vector3.forward)*Quaternion.FromToRotation(direction,Vector3.forward);holder.localScale*=(id.EndsWith("Heavy")?1.08f:.9f)/length;b=parts[0].bounds;foreach(var part in parts)b.Encapsulate(part.bounds);holder.position=hand.position+Vector3.forward*.23f+Vector3.up*.045f-b.center;
 }
 static void Socket(GameObject model,string id){if(id.EndsWith("Melee"))return;var bone=model.GetComponentsInChildren<Transform>().First(t=>id.EndsWith("Aoe")?t.name=="Beak_Top":UndercityProductionClips.Role(t.name)=="hand.R");var socket=new GameObject("ShotOrigin").transform;socket.SetParent(bone,false);var gun=model.GetComponentsInChildren<Renderer>().Where(r=>r.name.StartsWith("ServiceRifle")).ToArray();if(gun.Length>0){var b=gun[0].bounds;foreach(var r in gun)b.Encapsulate(r.bounds);socket.position=new Vector3(b.center.x,b.center.y,b.max.z+.025f);}else socket.position=bone.position+Vector3.forward*.25f;}
 static Texture2D Tex(string id,string file)=>string.IsNullOrEmpty(file)?null:AssetDatabase.LoadAssetAtPath<Texture2D>(Root+"Textures/"+id+"/"+file);
 public static void Proof(){
 Directory.CreateDirectory(Out);EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);RenderSettings.ambientLight=new Color(.28f,.3f,.35f);var light=new GameObject("Proof key").AddComponent<Light>();light.type=LightType.Directional;light.intensity=1.5f;light.transform.rotation=Quaternion.Euler(45,-35,0);var camera=new GameObject("Proof camera").AddComponent<Camera>();camera.orthographic=true;camera.orthographicSize=2.1f;camera.backgroundColor=new Color(.035f,.04f,.05f);camera.clearFlags=CameraClearFlags.SolidColor;camera.transform.rotation=Quaternion.Euler(50,35,0);camera.transform.position=new Vector3(0,1,0)-camera.transform.forward*10;
 var log=new System.Collections.Generic.List<string>();foreach(var id in Ids){var model=UnityEngine.Object.Instantiate(Resources.Load<GameObject>("Detailed/UndercityEnemies/Prefabs/"+id));var idle=Resources.Load<AnimationClip>("UndercityEnemyAnimations/"+id+"/Idle");idle.SampleAnimation(model,0);var bounds=VideoGame.Art.RenderedBounds(model);if(Mathf.Abs(bounds.min.y)>.05f)throw new Exception(id+" offground "+bounds);Capture(camera,id+"-idle.png");var clips=Resources.LoadAll<AnimationClip>("UndercityEnemyAnimations/"+id);if(clips.Length!=ActorAnimationBuilder.Names.Length)throw new Exception(id+" incomplete clipset "+clips.Length);foreach(var state in ActorAnimationBuilder.Names){var c=clips.First(x=>x.name==state);c.SampleAnimation(model,c.length*(state=="Death"?.9f:.3f));if(state=="Death"||state==(id.EndsWith("Melee")?"Melee":id.EndsWith("Aoe")?"Cast":"Fire"))Capture(camera,id+"-"+state+".png");var b=VideoGame.Art.RenderedBounds(model);if(!float.IsFinite(b.size.x)||b.size.magnitude>12)throw new Exception(id+" exploded "+state+" "+b);log.Add(id+" "+state+" length="+c.length+" bounds="+b);}
 var run=clips.First(c=>c.name=="RunForward");run.SampleAnimation(model,0);var first=Vertices(model);run.SampleAnimation(model,run.length*.3f);var second=Vertices(model);float delta=first.Zip(second,(a,b)=>Vector3.Distance(a,b)).Max();if(delta<.003f)throw new Exception(id+" rigid run "+delta);log.Add(id+" actualNativeOrWeightedRunDelta="+delta+" idleBounds="+bounds);Capture(camera,id+"-run.png");if(!id.EndsWith("Melee")&&!model.GetComponentsInChildren<Transform>().Any(t=>t.name=="ShotOrigin"))throw new Exception("Missing muzzle");UnityEngine.Object.DestroyImmediate(model);}
 File.WriteAllLines(Out+"unity-proof.txt",log);Debug.Log("UNDERCITY_PRODUCTION_PROOF_PASS:44clips finite,moving skins,grounded bodies and3sockets.");}
 static Vector3[] Vertices(GameObject model)=>model.GetComponentsInChildren<SkinnedMeshRenderer>().SelectMany(s=>{var mesh=new Mesh();s.BakeMesh(mesh);var v=mesh.vertices;UnityEngine.Object.DestroyImmediate(mesh);return v;}).ToArray();
 static void Capture(Camera c,string name){var rt=new RenderTexture(1100,1000,24){antiAliasing=4};c.targetTexture=rt;c.Render();RenderTexture.active=rt;var tex=new Texture2D(1100,1000,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,1100,1000),0,0);tex.Apply();File.WriteAllBytes(Out+name,tex.EncodeToPNG());c.targetTexture=null;RenderTexture.active=null;rt.Release();UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(tex);}
}
